/// <summary> Получает или устанавливает текущий режим маржи для спота. Допустимые значения: ["0", "1"] </summary>
/// <param name="_spotMarginMode"> Текущий режим маржи: 0=Regular margin mode, 1=Portfolio margin mode </param>
/// <returns> Текущий режим маржи </returns>
[DataMember('spotMarginMode')]
public str parmSpotMarginMode(str _spotMarginMode = spotMarginMode)
{
    spotMarginMode = _spotMarginMode;
    return spotMarginMode;
}
